375', 1, 'adjective', null, 'prominent', 'Flere prominente gæster deltog i festen.', 'Several prominent guests attended the party.'), ('væske', 'word', '95e8f0e0-ff26-5221-9c8f-b3339142c1b1', 1, 'noun', 'en', 'liquid, fluid', 'Drik rigelig væske i varmen.', 'Drink plenty of fluids in the heat.'), ('naturvidenskabelig', 'word', '34d5f506-d35e-5b31-98ec-38ce8f63cf20', 1, 'adjective', null, 'scientific (natural sciences)', 'Han har en naturvidenskabelig baggrund.', 'He has a background in the natural sciences.'), ('kreditor', 'word', 'd5687e90-e7ec-5a08-a132-54388a6fff45', 1, 'noun', 'en', 'creditor', 'Kreditorerne krævede pengene tilbage.', 'The creditors demanded the money back.'), ('stod', 'word', '1d075c80-fb97-572d-8ad4-1b08f25d1da5', 1, 'noun', 'et', 'gang, group (informal, of youths)', 'Der samlede sig et stod af unge ved stationen.', 'A group of youths gathered at the station.'), ('paradoks', 'word', '45b2b2d3-c8b9-5ac9-8a9a-5103b7ffc00d', 1, 'noun', 'et', 'paradox', 'Det er et paradoks, at han bliver mindre glad af mere penge.', 'It is a paradox that he becomes less happy with more money.'), ('reporter', 'word', '67f6487d-75df-57f2-8bc8-dae3b228bae9', 1, 'noun', 'en', 'reporter', 'En reporter stillede spørgsmål til ministeren.', 'A reporter asked the minister questions.'), ('hjemsted', 'word', '0f398a9c-370b-5236-87b9-352b32899376', 1, 'noun', 'et', 'registered office, domicile', 'Firmaets hjemsted er i København.', 'The company''s registered office is in Copenhagen.'), ('digtsamling', 'word', 'd09b7401-ed2b-553c-b780-8d7ed8fa283b', 1, 'noun', 'en', 'poetry collection', 'Hun udgav sin første digtsamling sidste år.', 'She published her first poetry collection last year.'), ('overgive', 'word', '99853052-e02f-5525-ba17-bc216c9dc74e', 1, 'verb', null, 'to surrender, to capitulate', 'Soldaterne valgte at overgive sig.', 'The soldiers chose to surrender.'), ('overgive', 'word', 'e34ac9f3-fd77-5da7-b6f5-89b605ca01a8', 2, 'verb', null, 'to hand over, to deliver', 'Han plejer at overgive pakken direkte til modtageren.', 'He usually hands the parcel directly to the recipient.'), ('holm', 'word', '864e8c36-eb11-50bc-b13a-c2b6b63f7c74', 1, 'noun', 'en', 'islet', 'Der ligger en lille holm midt i fjorden.', 'There is a small islet in the middle of the fjord.'), ('sekretariat', 'word', 'eede59ca-fc69-5c31-a79a-4822e5ebbc93', 1, 'noun', 'et', 'secretariat', 'Ansøgningen skal sendes til sekretariatet.', 'The application must be sent to the secretariat.'), ('revolutionær', 'word', '0051e3e7-9bc4-51fc-8345-b54bada3b9d4', 1, 'adjective', null, 'revolutionary', 'Det var en revolutionær opfindelse for sin tid.', 'It was a revolutionary invention for its time.'), ('forude', 'word', 'b2b59a52-44b9-5572-aa5d-5f7ce64216d7', 1, 'adverb', null, 'ahead (of the future, what lies in store)', 'Der venter store udfordringer forude.', 'Great challenges await ahead.'), ('suspendere', 'word', 'fdd2d986-35d3-55d1-979c-8e68a3807be8', 1, 'verb', null, 'to suspend (temporarily)', 'Spilleren blev suspenderet i tre kampe.', 'The player was suspended for three matches.'), ('måne', 'word', 'c4a14f4c-5a69-5f8b-8b52-ac7a6fbe5ca4', 1, 'noun', 'en', 'moon', 'Månen skinnede klart på himlen.', 'The moon shone brightly in the sky.'), ('bagsæde', 'word', '9f2772cd-fc47-5fcb-a0f2-c34d389fe0dc', 1, 'noun', 'et', 'back seat', 'Børnene sad på bagsædet.', 'The children sat in the back seat.'), ('latterlig', 'word', '79c7930f-17d9-5a9f-9599-6e6c6c312bae', 1, 'adjective', null, 'ridiculous, absurd', 'Han følte sig latterlig i det store kostume.', 'He felt ridiculous in the big costume.'), ('rækkefølge', 'word', '525562b4-3823-5dc4-8f95-d99ee6a7ebcd', 1, 'noun', 'en', 'order, sequence', 'Navnene stod i alfabetisk rækkefølge.', 'The names were in alphabetical order.'), ('kapel', 'word', 'bee121e8-7656-58ab-b732-77abfce22118', 1, 'noun', 'et', 'chapel', 'Begravelsen fandt sted i kirkens kapel.', 'The funeral took place in the church''s chapel.'), ('garage', 'word', '9244eb57-3857-5e24-a7cf-33477ed658ad', 1, 'noun', 'en', 'garage', 'Bilen står altid i garagen om natten.', 'The car is always in the garage at night.'), ('coronavirus', 'word', '14c1389a-acbf-505c-ba91-4bb67a0f2e8d', 1, 'noun', null, 'coronavirus', 'Hun blev smittet med coronavirus.', 'She was infected with coronavirus.'), ('retssikkerhed', 'word', 'b0de75c7-4475-5dc3-bdef-5d7d1ac0c29a', 1, 'noun', 'en', 'legal security, rule of law', 'Loven skal styrke borgernes retssikkerhed.', 'The law is meant to strengthen citizens'' legal protection.'), ('endegyldig', 'word', '299c572a-568e-50e2-aa13-112669e8c00d', 1, 'adjective', null, 'final, irrevocable', 'Dommen er endegyldig og kan ikke ankes.', 'The verdict is final and cannot be appealed.'), ('boghandel', 'word', '4dac5be8-8cd1-5e8e-bd34-49e2aeba3d1d', 1, 'noun', 'en', 'bookshop', 'Hun købte en roman i den lokale boghandel.', 'She bought a novel at the local bookshop.'), ('larm', 'word', '38d41d28-36fa-51b8-9100-b66480125d0a', 1, 'noun', 'en', 'noise, din', 'Der var en frygtelig larm fra byggepladsen.', 'There was a terrible noise from the building site.'), ('jakkesæt', 'word', '540bfeba-78ae-5444-aa41-622aa7f06a1d', 1, 'noun', 'et', 'suit (jacket and trousers)', 'Han havde jakkesæt på til jobsamtalen.', 'He wore a suit to the job interview.'), ('velegnet', 'word', '875c750e-4e39-512e-9fef-175b8cf4438b', 1, 'adjective', null, 'suitable, well-suited', 'Denne jord er velegnet til roser.', 'This soil is well-suited to roses.'), ('vågen', 'word', '143f4f95-12fd-5f40-98fd-918c84564492', 1, 'adjective', null, 'awake', 'Barnet var stadig vågen ved midnat.', 'The child was still awake at midnight.'), ('kantine', 'word', '69342cc7-be49-5125-ac8d-66157193f16b', 1, 'noun', 'en', 'canteen (at work, in an institution)', 'Vi spiser altid frokost i kantinen.', 'We always have lunch in the canteen.'), ('nazisme', 'word', '86a61a9c-0406-51e8-8b7a-83f1716212b0', 1, 'noun', 'en', 'Nazism', 'Bogen beskriver nazismens fremvækst.', 'The book describes the