gust.'), ('rede', 'word', 'faf2ab49-0806-597a-ac2f-ca62034646fa', 1, 'noun', 'en', 'nest', 'Fuglen byggede en rede i træet.', 'The bird built a nest in the tree.'), ('korps', 'word', '4144c12e-117a-5788-859c-202a6a172c12', 1, 'noun', 'et', 'corps, band (military or brass band)', 'Han spillede trompet i byens korps.', 'He played trumpet in the town band.'), ('værdighed', 'word', '6427597b-8d60-594a-aee5-1fece03e5ed9', 1, 'noun', 'en', 'dignity', 'Hun bar sin sygdom med stor værdighed.', 'She bore her illness with great dignity.'), ('kokain', 'word', 'e07444e5-a4cc-5ec1-a715-2632205318dc', 1, 'noun', null, 'cocaine', 'Politiet fandt kokain i bilen.', 'The police found cocaine in the car.'), ('stemple', 'word', '146c3e38-85b4-504e-9c10-17ff9c4a348a', 1, 'verb', null, 'to clock, to stamp', 'Medarbejderen skal stemple ind hver morgen.', 'The employee has to clock in every morning.'), ('fossil', 'word', 'c19beaf4-580a-5f35-9f4c-024e410e896e', 1, 'adjective', null, 'fossil (of energy, fuel)', 'Landet vil udfase fossil energi.', 'The country wants to phase out fossil energy.'), ('kommunistparti', 'word', 'b398c10c-f402-5c52-8e37-4c8eef29a090', 1, 'noun', 'et', 'communist party', 'Han var medlem af kommunistpartiet i mange år.', 'He was a member of the communist party for many years.'), ('deriblandt', 'word', '369c90da-c5a5-5d3d-8882-27305ae8ddd4', 1, 'adverb', null, 'among them, including', 'Mange gæster kom, deriblandt flere kendte kunstnere.', 'Many guests came, among them several well-known artists.'), ('mexicansk', 'word', '68ecedb7-065c-5ff4-8332-791e50600922', 1, 'adjective', null, 'Mexican', 'Vi spiste mexicansk mad på restauranten.', 'We ate Mexican food at the restaurant.'), ('forudsigelig', 'word', '358a4ee8-91b3-5213-be3a-d63a9b8b7ead', 1, 'adjective', null, 'predictable', 'Filmens slutning var meget forudsigelig.', 'The film''s ending was very predictable.'), ('tophold', 'word', '8ce21200-c3c3-527a-8f12-17188bb25009', 1, 'noun', 'et', 'top team, table-topper', 'Klubben er blevet et tophold i ligaen.', 'The club has become a top team in the league.'), ('snor', 'word', 'cc8e9ac7-aea9-59bf-a333-ccee913e6088', 1, 'noun', 'en', 'string, cord, leash', 'Hunden gik i snor gennem parken.', 'The dog was on a leash through the park.'), ('virtuel', 'word', '0a7af820-6792-5813-b52c-0e256c1ed38e', 1, 'adjective', null, 'virtual', 'Eleverne fik en virtuel rundvisning på museet.', 'The pupils got a virtual tour of the museum.'), ('afklaring', 'word', '6522f1ae-60f6-5be0-b4f3-8e1d3617e42b', 1, 'noun', 'en', 'clarification', 'Vi har brug for en afklaring, før vi går videre.', 'We need a clarification before we move on.'), ('veluddannet', 'word', '6e2ae3c7-3da4-54ce-bb9b-df4729a6374a', 1, 'adjective', null, 'well-educated', 'Hun er en veluddannet og erfaren sygeplejerske.', 'She is a well-educated and experienced nurse.'), ('database', 'word', '4505bb78-f676-55eb-8cff-f1223fb3fec0', 1, 'noun', 'en', 'database', 'Alle kunder er registreret i en database.', 'All customers are registered in a database.'), ('smutte', 'word', '5a88b276-f3eb-5933-8e9d-d163547a7001', 1, 'verb', null, 'to slip away, to sneak off', 'Katten smuttede ud ad døren.', 'The cat slipped out the door.'), ('magi', 'word', '4786c607-c891-5bb4-b580-d17b71989f88', 1, 'noun', 'en', 'magic', 'Børnene troede på magi i historien.', 'The children believed in magic in the story.'), ('mislykket', 'word', 'a8bae8fc-f0ed-5f01-980f-929ed679b5e0', 1, 'adjective', null, 'failed, unsuccessful', 'Projektet endte som et mislykket forsøg.', 'The project ended up as a failed attempt.'), ('patrulje', 'word', 'd39a6dd7-3a82-5824-b1bd-6e06371156c8', 1, 'noun', 'en', 'patrol', 'En patrulje gik gennem gaderne om natten.', 'A patrol walked through the streets at night.'), ('indrømmelse', 'word', 'e5241024-339a-5651-bd73-c2c0c6c91edc', 1, 'noun', 'en', 'admission, concession', 'Det var en svær indrømmelse for ham at lave.', 'It was a difficult admission for him to make.'), ('ensbetydende', 'word', 'f6a