ights.'), ('iagttage', 'word', 'dac7dd54-0650-56d6-b09b-7f12be7f8f92', 1, 'verb', null, 'to observe', 'Forskeren plejer at iagttage dyrenes adfærd i timevis.', 'The researcher usually observes the animals'' behaviour for hours.'), ('sydpå', 'word', 'ea21f94d-a8f1-53d6-9429-1bd4aebecdf8', 1, 'adverb', null, 'southward, to the south', 'De kørte sydpå for at undgå kulden.', 'They drove south to avoid the cold.'), ('parameter', 'word', '96c998f6-3cce-5cdc-8288-f7226e17f471', 1, 'noun', null, 'parameter', 'Ingeniøren justerede flere parameter i systemet.', 'The engineer adjusted several parameters in the system.'), ('hertug', 'word', 'f38b9644-2c24-5814-a2ad-19049ab64b79', 1, 'noun', 'en', 'duke', 'Hertugen ejede store landområder.', 'The duke owned large areas of land.'), ('kostume', 'word', '66ad269d-388b-5dd7-88d9-ebdd11dee52f', 1, 'noun', 'et', 'costume (fancy dress, theatrical)', 'Hun syede selv sit kostume til festen.', 'She sewed her own costume for the party.'), ('tilberede', 'word', 'c31f5f0d-8a05-5ce5-92f9-c93e80aac92c', 1, 'verb', null, 'to prepare, to cook (food)', 'Han tilberedte middagen med stor omhu.', 'He prepared dinner with great care.'), ('anmode', 'word', '9a59f303-9791-556d-9da4-3a5866976712', 1, 'verb', null, 'to request, to petition', 'Hun anmodede om en forlængelse af fristen.', 'She requested an extension of the deadline.'), ('suse', 'word', '6dc7ed70-e19a-56b4-872e-8a18bbd04f8c', 1, 'verb', null, 'to whizz, to speed (noisily)', 'Bilerne susede forbi på motorvejen.', 'The cars whizzed past on the motorway.'), ('grusom', 'word', '2d777414-7cc4-51db-9a3d-de9c8eb7e46f', 1, 'adjective', null, 'cruel', 'Det var en grusom forbrydelse.', 'It was a cruel crime.'), ('franskmand', 'word', 'f2603a6e-511c-5b21-b019-6d04e70a3838', 1, 'noun', 'en', 'Frenchman', 'Hun mødte en franskmand under ferien.', 'She met a Frenchman while on holiday.'), ('herudover', 'word', '9332741f-c3ac-5089-8126-93a3250eab6f', 1, 'adverb', null, 'furthermore, besides this', 'Herudover skal vi også huske at ringe til kunden.', 'Besides this, we must also remember to call the customer.'), ('sprøjte', 'word', '90e23644-d4eb-58ea-a072-4cb3d7cb90bb', 1, 'verb', null, 'to spray, to squirt', 'Hun sprøjtede vand på blomsterne.', 'She sprayed water on the flowers.'), ('afgrøde', 'word', '3094a726-bb70-5489-b5c9-64f862656891', 1, 'noun', 'en', 'crop, harvest', 'Bønderne høstede en god afgrøde i år.', 'The farmers harvested a good crop this year.'), ('invadere', 'word', 'f2bc1d02-f965-504f-9229-6aded6b12a9a', 1, 'verb', null, 'to invade', 'Hæren invaderede landet uden varsel.', 'The army invaded the country without warning.'), ('universel', 'word', '75f48647-c9f7-583c-a9a0-991adaef030d', 1, 'adjective', null, 'universal', 'Musik er et universelt sprog.', 'Music is a universal language.'), ('potential', 'word', '01a26ec3-857d-50b4-8d4d-74ec4da974b3', 1, 'noun', 'et', 'potential', 'Firmaet har et stort potential for vækst.', 'The company has great potential for growth.'), ('søgelys', 'word', 'b16f8424-3824-5db2-9053-9d2f513d1715', 1, 'noun', 'et', 'spotlight, attention (in ''in the spotlight'')', 'Sagen kom i søgelyset efter avisens artikel.', 'The case came into the spotlight after the newspaper article.'), ('skælde', 'word', '5e83a488-77ce-5171-bde4-4ee5d578dbc4', 1, 'verb', null, 'to scold, to tell off', 'Læreren skældte drengene ud for larmen.', 'The teacher told the boys off for the noise.'), ('stab', 'word', '8b1ba7b6-6cae-5278-a657-4065ace4d6ca', 1, 'noun', 'en', 'staff', 'Firmaet har en dygtig stab af medarbejdere.', 'The company has a skilled staff of employees.'), ('årsregnskab', 'word', '519a45ff-5338-5278-9650-7d26c8491e97', 1, 'noun', 'et', 'annual accounts', 'Bestyrelsen godkendte årsregnskabet i marts.', 'The board approved the annual accounts in March.'), ('lederskab', 'word', 'b69cca95-15d0-51d3-9e05-4141ce9742a4', 1, 'noun', 'et', 'leadership', 'Hun viste stærkt lederskab under krisen.', 'She showed strong leadership during the crisis.'), ('kontekst', 'word', 'a3e1d316-4f6a-560f-9d89-3163394409d7', 1, 'noun', 'en', 'context', 'Citatet skal forstås i sin rette kontekst.', 'The quote must be understood in its proper context.'), ('plukke', 'word', '187bb584-d7ab-5840-ad71-182980dd3106', 1, 'verb', null, 'to pick (fruit, flowers)', 'Børnene plukkede jordbær i haven.', 'The children picked strawberries in the garden.'), ('dråbe', 'word', 'a11566b3-3aec-5e65-a334-7ab865c40c63', 1, 'noun', 'en', 'drop', 'En dråbe regn faldt på hendes kind.', 'A drop of rain fell on her cheek.'), ('klubhus', 'word', 'a07938cf-dd99-5115-83c2-3841b86d9492', 1, 'noun', 'et', 'clubhouse', 'Spillerne mødtes i klubhuset før kampen.', 'The players met in the clubhouse before the match.'), ('firkantet', 'word', 'd23bae90-31a5-55c9-b98f-6bef28de9f6b', 1, 'adjective', null, 'square, rectangular', 'Bordet har en firkantet plade.', 'The table has a square top.'), ('usund', 'word', '19ef07cf-5ee8-511b-8ac9-9d21958a69c5', 1, 'adjective', null, 'unhealthy', 'Fastfood betragtes ofte som usund mad.', 'Fast food is often considered unhealthy food.'), ('overordentlig', 'word', '37a876ee-3492-5b74-9fc6-655f1e2b8472', 1, 'adjective', null, 'extraordinarily', 'Hun var overordentlig dygtig til sit arbejde.', 'She was extraordinarily good at her job.'), ('afsone', 'word', 'e4cea45a-922c-5649-96a9-d050a5e38480', 1, 'verb', null, 'to serve (a sentence)', 'Han skal afsone sin dom i to år.', 'He has to serve his sentence for two years.'), ('regnestykke', 'word', 'a3097e33-6147-531f-a9f5-9b4fca59accf', 1, 'noun', 'et', 'sum, arithmetic problem', 'Eleven løste regnestykket på tavlen.', 'The pupil solved the sum on the blackboard.'), ('bestride', 'word', '8fea9514-91bf-583a-8fbb-54dd48669509', 1, 'verb', null, 'to dispute, to contest', 'Han bestrider, at han var til stede.', 'He disputes that he was present.'), ('kredse', 'word', 'c7e7a2c7-7459-5825-aa14-95e2dd793e8a', 1, 'verb', null, 'to circle', 'Ørnen kredsede højt over dalen.', 'The eagle circled high above the valley.'), ('pc', 'word', 'f9c20ab1-306f-5991-93c2-ec4cfe7c756b', 1, 'noun', 'en', 'PC, personal computer', 'Han købte en ny pc til arbejdet.', 'He bought a new PC for work.'), ('anno', 'word', '06419e38-63db-58d7-a047-eb38161903bb', 1, 'phrase', null, 'in the year (with a date)', 'Bygningen er opført anno 1875.', 'The building was erected in the year 1875.'), ('bestride', 'word', '0915b7e1-ebb2-5587-8cbc-bb641b6bcc36', 2, 'verb', null, 'to hold (an office)', 'Hun bestrider stillingen som direktør.', 'She holds the position of director.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
